&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Stage 1:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;Screening&amp;nbsp;Call with Talent Team&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Stage 2:&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Cloud Security &amp;amp; Engineering Best Practices interview&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&lt;strong&gt;Stage 3 (optional):&lt;/strong&gt; Team interview&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We always aim to stick to the above process, however there may be occasions when an&amp;nbsp;additional&amp;nbsp;interview stage is needed for us to be sure&amp;nbsp;we’re&amp;nbsp;hiring the right&amp;nbsp;fit for the role.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;HIRING LOCATIONS📍&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Here are the locations that we are looking to hire from for this role. Please note, we are not looking to engage with candidates outside of these locations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;UK&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;All new team members start their first day in our office to collect the equipment needed to work remotely.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;ABOUT FORM3&amp;nbsp;💭&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Revolutionising the world of payments with our cloud-native, multi-cloud platform. For more information about Form3, check out the following pages:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.form3.tech/platform&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;What we do&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.form3.tech/culture&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Life at Form3&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.youtube.com/@Form3Cloud/podcasts&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;P&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;ayments Cannot&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Fail&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;Series&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;|&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://techpodcast.form3.tech/episodes&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;.Tech&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;&amp;nbsp;Podcast&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;OUR DEI&amp;amp;B COMMITMENT&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We hire talented people from a variety of backgrounds and experiences and are committed to a work environment based on diversity, open-mindedness and curiosity. We’re united by our company values (we even created them together!) and we celebrate our unique differences.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Our employee lifecycle processes are designed to embrace equal opportunity and prevent discrimination against our people regardless of personal characteristics. It is our strong belief that the more inclusive and belonging we are as a business, the better our work will be.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;As an inclusive employer, we guarantee to interview all neurodiverse and physically disabled applicants who meet the minimum criteria for this role. We also encourage candidates to notify us of any reasonable adjustments that may be required during the recruitment process. This includes providing job adverts in alternative, accessible formats or adjustments required at interview stage.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;If you consider yourself to be neurodiverse or physically disabled under the UN definition of disability and would like to be considered under this scheme and/or require any reasonable adjustments please let us know by sending an email to &lt;/span&gt;&lt;a ----- ----- data-contrast=&quot;none&quot;&gt; clearly stating your consent for us to process this data. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;For more information please refer to our &lt;/span&gt;&lt;a href=&quot;https://www.form3.tech/legal/recruitment-data-policy&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Recruitment Data Policy&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p&gt;&lt;strong&gt;Department: &lt;/strong&gt;One Unilever&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location: &lt;/strong&gt;London&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Contact type: &lt;/strong&gt;12 months FTC&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Full Time/Part time:&lt;/strong&gt; Full Time&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Reporting into: &lt;/strong&gt;Chief Strategy Officer, OUL.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Ogilvy:   &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Ogilvy UK has been creating iconic ideas that deliver impact at scale for clients ever since David Ogilvy founded the company in 1948. Ogilvy UK specialises in bringing together brand advertising, customer experience marketing, PR, influence and consulting, all fuelled by Behavioural Science. Our world-class award-winning creative campaigns deliver solutions for clients including Molson Coors (owner of Madrí beer), Valeo Foods UK (owner of Kettle Chips and Rowse Honey), Argos, Mondelēz International, Unilever, TK Maxx and Pernod Ricard.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;In 2023, Ogilvy UK celebrated their 75th anniversary and was the most awarded agency in Europe. Ogilvy is home to the largest influencer marketing practice globally, and hosts the world’s biggest festival of behavioural science and creativity, Nudgestock – now in its 12th year.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The Role:&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As a Global Strategy Director focused on the dynamic and social-forward beauty and wellness sector at Ogilvy, you will play a pivotal role in leading the development of strategic plans tailored to meet the client&#39;s distinct objectives and needs. You&#39;ll stay at the forefront of the latest beauty and wellbeing trends, cultural insights, and best practices in the realm of creative strategy development while advocating for diversity of thought and championing inclusive approaches. Collaborating closely with clients, you&#39;ll gain a deep understanding of their global business, target audiences, and brand values, translating this knowledge into compelling culturally driven campaigns that resonate with their customers and drive tangible outcomes.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;You&#39;ll actively contribute to social and cultural insight mining to shape the agency&#39;s creative output. Your recommendations and inventive solutions will pave the way for clients to amplify trends and topics effectively.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Key Responsibilities/The Do’s:&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;· Lead the development of bespoke strategic plans that align with clients&#39; unique goals, incorporating the latest trends and best practices.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Work in a social-first culture-forward way to build big campaign ideas.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Collaborate closely with clients to grasp their business, target audience, and brand ethos, and formulate campaigns that resonate and yield results.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Conduct in-depth research and analysis, using social tools, to pinpoint emerging trends, influencers, and topics that can enhance compelling content and campaigns.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Partner with internal teams—creative, account, and media—to ensure campaign integration aligns with overall brand strategy.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Emerge as a thought leader both within the agency and the industry at large, sharing insights, trends, and best practices with teams and clients.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Stay updated on the latest trends, technologies, and tools in influence and social marketing, applying this knowledge to enhance campaign performance.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Develop influential and innovative social strategies for high-profile clients, deeply rooted in culture and deserving of attention.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Collaborate with planners, creatives, and creators to collaboratively address challenges and deliver exceptional work.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Recognise opportunities for clients to harness and amplify trends and topics.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Enhance the agency&#39;s creative output through insightful recommendations and inventive problem-solving.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Requirements/Experience We Value:&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;· Good experience in social and influencer marketing, with a focus on formulating and executing strategic campaigns for notable consumer brands.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Proficiency in working within a creative agency or similar setting, with a strong grasp of the creative process and effective collaboration with creative teams.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Proven track record of driving successful campaigns that deliver tangible business outcomes for clients.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Familiarity with the global beauty and wellbeing industry and experience working on female power brands.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Exceptional strategic thinking and planning abilities, crafting tailored plans that cater to individual client needs and objectives.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Experience in social-first strategic planning, leading to big 360 campaigns that drive conversion through culture.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Strong project management capabilities, managing multiple global campaigns and priorities concurrently.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Excellent interpersonal skills, fostering strong relationships with clients and internal teams.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Highly skilled in creative thinking and innovative problem-solving.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Understanding of paid media integration within influence and social campaigns.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Strong presentation skills, effectively conveying intricate ideas and strategies to clients and internal teams.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;How we help you Thrive:&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;·  25 days annual leave + 1 Volunteer Day &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Bupa Healthcare&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Enhanced Maternity, Adoption and Shared Parental Leave&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· We have a Flexible Working Model with core working hours: 10am – 4pm&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· A 1.5:1 Matching Pension Structure&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Wellbeing and Health: Up to £25.00 per month towards physical or online exercise class membership, Unmind membership, LifeWorks tool and annual eye tests and development budgets and Wellbeing incentives and activities throughout the year &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Season Ticket Loan and Cycle to Work Scheme&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;· Life Assurance&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p class=&quot;x_MsoNormal&quot;&gt;Our ambition is to attract the very best diverse talent to Ogilvy, and to be the employer of choice in the UK. We want everyone to feel welcome when they join us, and once they’re here, for them to want to stay with us, grow their career, and to feel they belong with us.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We are an equal opportunity employer and we’re committed to creating an inclusive, welcoming environment for everyone who wants to work at Ogilvy. For us, diversity, equity and inclusion is integrated into everything that we do. We believe that for creativity to flourish, everything about how we work must have diversity at its core. Your race, colour, ethnic, religion, gender, gender identity, national origin, sexual orientation, age, marital status, disability, have no bearing on our hiring decisions, but we encourage everyone to feel free to express their true selves in an environment we are consistently striving to make as inclusive as possible.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We aim to facilitate an accessible and positive application experience for all candidates. If you require any adjustments from us to support you through the process or expect to require any adjustments to working conditions to be able to best perform in the role, please let us know. We are happy to consider all reasonable adjustments.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;If you live with a disability and you would like to take advantage of our offer of a guaranteed interview under the Disability Confident Scheme, please ensure you fill out our voluntary Equal Opportunities Questionnaire when applying.&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Social Account Director&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Department:&lt;/strong&gt; Social&lt;br&gt;&lt;strong&gt;Location: &lt;/strong&gt;London&lt;br&gt;&lt;strong&gt;Contact&amp;nbsp;type:&lt;/strong&gt; 12-Month Fixed Term Contract (Maternity Cover)&lt;br&gt;&lt;strong&gt;Full Time/Part time:&lt;/strong&gt; Full Time&lt;br&gt;&lt;strong&gt;Reporting into:&lt;/strong&gt; Client Partner&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Ogilvy: &lt;br&gt;&lt;br&gt;&lt;/strong&gt;Ogilvy UK has been creating iconic ideas that deliver impact at scale for clients ever since David Ogilvy founded the company in 1948. The agency specialises in bringing together brand advertising, customer experience marketing, PR, influence and consulting, all fuelled by Behavioural Science. Our world-class award-winning creative campaigns deliver solutions for clients including Sainsbury’s, Lloyds Banking Group, Madri, Unilever and Mondelēz International.&amp;nbsp;&lt;br&gt;&lt;br&gt;Ogilvy’s influencer marketing practice is the largest globally; we are proud to be the most awarded influencer agency for six years running and the recipient of the Cannes Grand Prix for Social &amp;amp; Creator for two consecutive years.&amp;nbsp;&amp;nbsp;&lt;br&gt;&lt;br&gt;Ogilvy UK also hosts the world’s biggest festival of behavioural science and creativity, Nudgestock – which is now in its 12th year. James Murphy is the CEO of Ogilvy Group UK, which includes Ogilvy UK and New Commercial Arts (NCA), a boutique creative agency he co-founded in 2020, recently acquired by WPP.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About this role:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Social and content has never been more important for clients. Showing up authentically, with intention, across social platforms helps brands connect with their audiences. It helps them to sell and serve better.&lt;/p&gt;
&lt;p&gt;This role provides the opportunity to work on a really exciting client that have a portfolio of soft drinks brands. You will have the opportunity to manage key campaigns across the year that will involve working with our strategy, creative and production team to deliver best in class campaigns and content.&lt;br&gt;This role is perfect for someone that has a wide knowledge of social – they will have experience managing content and campaigns that build brand advocacy as well having an understanding of how to create hard working assets that drive to purchase. The ideal candidate will know how to effectively lead an account, steering processes and ways of working internally, with agency partners and with our clients.&lt;br&gt;&lt;br&gt;The ideal candidate will have their finger on the pulse across all things social – from what’s trending that could be a good opportunity for a brand to leverage, through to a thorough understanding of how data, strategy, community management feed into the success of a brands social media presence.&lt;/p&gt;
&lt;p&gt;Whilst the candidate will have a passion for delivering best in class social campaigns, they will also be required to lead in other areas of the marketing mix, and the idea candidate will have some integrated experience.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;A bit about you:&lt;br&gt;&lt;br&gt;&lt;/strong&gt;We are flexible on whether you have come from an agency of client background, but we think the following are really important for this role:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Organised and autonomous; you’ll be responsible for motivating the team to do great work, whilst anticipating any areas that may hinder the success of the campaign&lt;/li&gt;
&lt;li&gt;Whilst you will work with a Account Manager to support with budgets and timings, you will also be well averse in taking this on and have an excellent understanding of processes and what it takes to deliver social campaigns on budget and on time&lt;/li&gt;
&lt;li&gt;Financially savvy; you’ll need to work with the rest of the agency team to deliver proposals that are within the client’s budgets and ensure successful delivery&lt;/li&gt;
&lt;li&gt;You will be an excellent communicator; providing clear succinct guidance to the internal teams as well as being able to present the work to clients&lt;/li&gt;
&lt;li&gt;You’ll be someone that loves to get stuck into a task, and collaborate with the client and agency teams, and make stuff happen!&lt;/li&gt;
&lt;li&gt;Experience within the retail sector is not essential but would be helpful&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;More about your role at Ogilvy:&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As a Social Account Director you&amp;nbsp;lead&amp;nbsp;large,&amp;nbsp;more complex projects, armed with your experience and proven ability to think and do.&amp;nbsp;You are able to problem&amp;nbsp;solve and&amp;nbsp;create&amp;nbsp;highly effective&amp;nbsp;and fruitful&amp;nbsp;working relationships&amp;nbsp;with clients and&amp;nbsp;colleagues, collaborating with other&amp;nbsp;Capabilities and Crafts&amp;nbsp;instinctively.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;You may also have a solid understanding of strategy and always ensure that you and the team are working towards strategic objectives.&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Has a relationship with&amp;nbsp;mid-level&amp;nbsp;clients&amp;nbsp;that&amp;nbsp; is&amp;nbsp;one of trusted partner, based on proven track record of delivery.&lt;/li&gt;
&lt;li&gt;Is able to confidently lead conversations and problem solve in the moment as required, and act as a point of escalation for junior clients.&lt;/li&gt;
&lt;li&gt;Has strong skills in paid and organic social and has worked across a wide variety of clients and projects from small response driven workstreams to larger more complex social experiences across multi platforms and touch points&lt;/li&gt;
&lt;li&gt;Understands how to work and lead project delivery in a Social first environment, as well as as part of an integrated team.&lt;/li&gt;
&lt;li&gt;Is confident managing multi-level stakeholders in complex matrix organisations as well managing resources and teams, across all levels, with diverse skills and personalities.&lt;/li&gt;
&lt;li&gt;Understands the strategic, and business context the client is operating in and uses this knowledge to develop&amp;nbsp;solutions&amp;nbsp;and&amp;nbsp;approach tasks in a way that is effective for the client&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Collaborates confidently with other capabilities and crafts in service of finding the best Social creative solution to the&amp;nbsp;clients&amp;nbsp;business problem.&amp;nbsp; Is seen as a champion for the craft with all those they come in to contact with.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Demonstrates their ability for creative problem solving in how they approach every task – whether that’s identifying a way to improve the internal&amp;nbsp;process, ideating for an innovative social solution, or&amp;nbsp;co-creating an inspiring way to sell in the work. Able to consider different angles on a brief – a&amp;nbsp;non linear&amp;nbsp;thinker.&lt;/li&gt;
&lt;li&gt;Takes responsibility for larger projects. And acts accountable for both the work, and the process.&lt;/li&gt;
&lt;li&gt;Understands that they are accountable for the actions of the account team reporting into them on projects; guiding them and intervening and managing up as required.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Will manage client expectations when having to charge more for additional work in a manner which does not expose the agency to financial risk&lt;/li&gt;
&lt;li&gt;Is well informed about the commercials of all projects they are responsible for, managing those below them to meet agreed targets&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Able to maintain strong partnership with internal stakeholders across all crafts in and support cross functional agendas for the benefit of the company and the client.&lt;/li&gt;
&lt;li&gt;Has strong relationship with their days to day clients and wider client stakeholders, and uses these relationships to help protect the work, strengthen the relationships and activate new opportunities.&lt;/li&gt;
&lt;li&gt;Acts as an escalation point for the team in resolving issues. Supports the team in confidently navigating through problems&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;br&gt;&lt;strong&gt;How we help you Thrive:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;25 days annual leave + 1 Volunteer Day&lt;/li&gt;
&lt;li&gt;Bupa Healthcare&lt;/li&gt;
&lt;li&gt;Enhanced Maternity, Adoption and Shared Parental Leave&lt;/li&gt;
&lt;li&gt;Flexible Working Model with core working hours: 10am – 4pm&lt;/li&gt;
&lt;li&gt;A 1.5:1 Matching Pension Structure&lt;/li&gt;
&lt;li&gt;Wellbeing and Health: Up to £25.00 per month towards physical or online exercise class membership, Unmind membership, LifeWorks tool and annual eye tests.&lt;/li&gt;
&lt;li&gt;Season Ticket Loan and Cycle to Work Scheme&lt;/li&gt;
&lt;li&gt;Life Assurance&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p class=&quot;x_MsoNormal&quot;&gt;Our ambition is to attract the very best diverse talent to Ogilvy, and to be the employer of choice in the UK. We want everyone to feel welcome when they join us, and once they’re here, for them to want to stay with us, grow their career, and to feel they belong with us.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We are an equal opportunity employer and we’re committed to creating an inclusive, welcoming environment for everyone who wants to work at Ogilvy. For us, diversity, equity and inclusion is integrated into everything that we do. We believe that for creativity to flourish, everything about how we work must have diversity at its core. Your race, colour, ethnic, religion, gender, gender identity, national origin, sexual orientation, age, marital status, disability, have no bearing on our hiring decisions, but we encourage everyone to feel free to express their true selves in an environment we are consistently striving to make as inclusive as possible.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We aim to facilitate an accessible and positive application experience for all candidates. If you require any adjustments from us to support you through the process or expect to require any adjustments to working conditions to be able to best perform in the role, please let us know. We are happy to consider all reasonable adjustments.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;If you live with a disability and you would like to take advantage of our offer of a guaranteed interview under the Disability Confident Scheme, please ensure you fill out our voluntary Equal Opportunities Questionnaire when applying.&lt;/p&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Senior Social Strategist&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Department:&lt;/strong&gt; Social Strategy&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location:&lt;/strong&gt;&amp;nbsp;London&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Contract&amp;nbsp;type:&lt;/strong&gt; 12-month Fixed Term Contract&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Full Time/Part time:&lt;/strong&gt; Full time&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Reporting into:&lt;/strong&gt; Head of Social Strategy&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Ogilvy:&amp;nbsp;&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Ogilvy UK has been creating iconic ideas that deliver impact at scale for clients ever since David Ogilvy founded the company in 1948. We are the most awarded agency in Europe and we specialise in bringing together brand advertising, customer experience marketing, PR, influence and consulting, all fuelled by Behavioural Science. Our world-class award-winning creative campaigns deliver solutions for clients&amp;nbsp;including Molson Coors, Mondelēz International, Unilever, and many more. &amp;nbsp;Ogilvy is reimagining how brands are built in the age of social, and has built a team of social experts who embrace the chaos of social, using it as the business engine behind the brand and creating earned-first impact through creativity.&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The Role:&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This is an exciting opportunity at Ogilvy to play a key role in elevating our social capabilities for 2026 and beyond, helping us redefine our social and content offer and realize our new global ambition of ‘building social brands’. Ogilvy is seeking an experienced &lt;strong&gt;Senior Strategist&lt;/strong&gt; who will sit within our Social Strategy team. They will be responsible for collaborating closely with clients to gain a deep understanding of their businesses, target audiences, and brand values and developing bold creative strategies that answer their unique challenges. You’ll take full ownership of key workstreams and use your deep social knowledge to develop innovation strategic solutions. You’ll also benefit from being part of Ogilvy’s wider strategy community where you’ll work alongside - and learn from - specialised strategists in PR, influence, brand and experience, as well as experts in behavioural science and consulting.&lt;/p&gt;
&lt;p&gt;As a mentor and a leader, you’ll help guide and support junior team members in their professional growth and strategic development, because you know what great social strategy looks like. You’ll advocate for diversity of thought and champion inclusive approaches from the team, because you know that strategy can come in lots of different flavours and a great insight can be found anywhere. &amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Key Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Strategic development and execution:&lt;/strong&gt; Lead the development of social and content strategies, playbooks, workshops, and measurement frameworks for clients (with guidance from the team lead on bigger projects). Adapt the strategic output based on client need (e.g. tissue decks, strategic responses, paths forward, workshops, etc). Define the brands’ role of social and create messaging frameworks with clear content pillars, all laddering back to the overall brand vision and supported by social intelligence data. Build trust and rapport with clients and colleagues and sell them on your strong strategic thinking.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Creative briefing: &lt;/strong&gt;Develop strategic creative territories and write clear briefs for the creative team to explore them. Articulate social-first creative ideas to clients and help them understand how/ why they work.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Insight mining and creative problem solving:&lt;/strong&gt;. Intuitively understand client challenges and leverage business data to get to the core of the problem. Uncover unexpected insights from a diverse range of sources to help shape your social communication strategies. Interpret reporting data to suggest improvements to campaign or organic social performance.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Impactful storyteller and engaging presenter: &lt;/strong&gt;Inspire internal and external stakeholders on the strategic opportunities of social and present narratives in compelling and memorable ways. Design and lead workshops/ client presentations and act as an ideas catalyst and strategic partner for clients, asking insightful questions to get clients thinking differently about their brand on social.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Leading and mentoring junior team members:&lt;/strong&gt;. Provide mentorship and guidance to junior team members, fostering their growth and leading by example. Contribute to Ogilvy&#39;s culture of excellence, innovation, and impactful creativity. Know what a great social strategy looks like and help upskill team members on that thinking.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Thinking social first, not social only:&amp;nbsp;&lt;/strong&gt;Possess a deep understanding of social best practises, trends, tools and technologies and apply this knowledge to clients to enhance their campaign performance. Share industry insights and best practices to inspire internal teams and clients. Understand and articulate how social works within the larger media ecosystem and within the client’s broader campaign/ business goals.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Collaborating cross functionally:&lt;/strong&gt; Think laterally about how to uncover unique insights by working closely with our in-house Marketing Science partners to test hypotheses and get to the right answers. Ensure alignment of campaigns with brand strategies by collaborating effectively with cross-functional teams. Contribute to new business pitches and proposals, infusing industry insights and creative ideas.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Requirements:&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience designing tailored strategic social plans that address diverse business goals, incorporating latest social trends and best practises.&lt;/li&gt;
&lt;li&gt;Relentlessly curious about social, with a deep knowledge of social trends, platforms and aesthetics. A proactive approach to staying updated with industry trends, tools, and technologies.&lt;/li&gt;
&lt;li&gt;Experience defining the role of social for brands and creating messaging frameworks for brands with clear content territories/ pillars.&lt;/li&gt;
&lt;li&gt;Experience in creative agencies or equivalent environments. Ability to work in a fast-paced environment, managing multiple projects and priorities efficiently.&lt;/li&gt;
&lt;li&gt;Demonstrated ability to provide mentorship and guidance to junior team members. Commitment to fostering inclusivity and embracing innovative approaches to strategy development.&lt;/li&gt;
&lt;li&gt;Effective presentation skills to convey ideas and strategies convincingly. Ability to lead presentations/ workshops confidently.&lt;/li&gt;
&lt;li&gt;Ability to collaborate effectively with XFN teams and with colleagues from diverse disciplines and backgrounds.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;How we help you Thrive:&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;25 days annual leave + 1 Volunteer Day&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Bupa Healthcare&lt;/li&gt;
&lt;li&gt;Enhanced Maternity, Adoption and Shared Parental Leave&lt;/li&gt;
&lt;li&gt;We have a Flexible Working Model with core working hours: 10am – 4pm&lt;/li&gt;
&lt;li&gt;A 1.5:1 Matching Pension Structure&lt;/li&gt;
&lt;li&gt;Wellbeing and Health: Up to £25.00 per month towards physical or online exercise class membership, Unmind membership, LifeWorks tool and annual eye tests and development budgets and Wellbeing incentives and activities throughout the year&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Season Ticket Loan and Cycle to Work Scheme&lt;/li&gt;
&lt;li&gt;Life Assurance&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p class=&quot;x_MsoNormal&quot;&gt;Our ambition is to attract the very best diverse talent to Ogilvy, and to be the employer of choice in the UK. We want everyone to feel welcome when they join us, and once they’re here, for them to want to stay with us, grow their career, and to feel they belong with us.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We are an equal opportunity employer and we’re committed to creating an inclusive, welcoming environment for everyone who wants to work at Ogilvy. For us, diversity, equity and inclusion is integrated into everything that we do. We believe that for creativity to flourish, everything about how we work must have diversity at its core. Your race, colour, ethnic, religion, gender, gender identity, national origin, sexual orientation, age, marital status, disability, have no bearing on our hiring decisions, but we encourage everyone to feel free to express their true selves in an environment we are consistently striving to make as inclusive as possible.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We aim to facilitate an accessible and positive application experience for all candidates. If you require any adjustments from us to support you through the process or expect to require any adjustments to working conditions to be able to best perform in the role, please let us know. We are happy to consider all reasonable adjustments.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;If you live with a disability and you would like to take advantage of our offer of a guaranteed interview under the Disability Confident Scheme, please ensure you fill out our voluntary Equal Opportunities Questionnaire when applying.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;&amp;nbsp;Account Director&lt;/strong&gt; &lt;br&gt;Corpsumer PR&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Department: &lt;/strong&gt;Consumer PR &amp;amp; Influence&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Location: &lt;/strong&gt;London&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Contract Type: &lt;/strong&gt;Fixed-Term 12-Months&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Full Time/Part time: &lt;/strong&gt;Full Time&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Reporting into:&lt;/strong&gt; Business Director / Client Partner&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The Role:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are seeking a talented individual to join our team as an Account Director on a large technology account. You’ll spearhead high-impact PR campaigns and run a fast-paced press office that spans both consumer and corporate remits.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;You are a natural problem solver who thrives on challenge and builds instinctive, collaborative relationships across different agency Capabilities and Crafts. Combining a deep understanding of strategy with flawless execution, you will ensure the team constantly delivers creative, quality work that moves the needle for our client.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About You:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;8+ years’ of PR experience, ideally with a “corpsumer” background&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A genuine interest in consumer tech and the evolving world of AI&lt;/li&gt;
&lt;li&gt;Solid understanding of the UK media landscape and established journalist relationships&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A proven track record of managing fast-paced press offices and navigating complex, multi-stakeholder projects spanning consumer, corporate and policy remits&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Established as a trusted advisor to mid-level clients, with a strong grasp of their business context, challenges and goals&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A natural problem-solver who looks at briefs from unexpected angles and pushes for innovative ways to sell in and execute work&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Takes ownership of large projects and is accountable for both work and process&amp;nbsp;&lt;/li&gt;
&lt;li&gt;An empowering mentor who guides junior team members, manages up effectively, and fosters a collaborative team culture&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Commercially astute, with experience managing budgets, scoping work, and resource planning to hit targets&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Key Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Build and maintain strong relationships with clients, becoming a trusted partner and advisor&lt;/li&gt;
&lt;li&gt;Lead and manage the fast-paced press office function, and projects across consumer, corporate and policy remits&lt;/li&gt;
&lt;li&gt;End-to-end delivery of projects, from briefing, scoping and resourcing to execution and measurement, working with other Capabilities and Crafts instinctively&lt;/li&gt;
&lt;li&gt;Cultivate and maintain strong relationships with key stakeholders, including media, creators and internal client teams&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Oversee a team of Account Managers and Account Executives, providing guidance and mentorship, while also acting as an escalation point to support the team in resolving issues&lt;/li&gt;
&lt;li&gt;Collaborate closely with integrated teams across Ogilvy, including social media and influencer marketing, to spot opportunities and align on campaigns and projects, where relevant&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Foster a culture of creativity, collaboration, and innovation within the agency and among the account management team&lt;/li&gt;
&lt;li&gt;Serve as the main point of contact for mid-senior clients, managing communication and expectations throughout the project lifecycle&lt;/li&gt;
&lt;li&gt;Ensure all campaign materials, including press releases and assets, are delivered to a high standard and align with the client&#39;s messaging and objectives&lt;/li&gt;
&lt;li&gt;Lead regular client meetings and status updates to review project progress and discuss any changes or adjustments needed&lt;/li&gt;
&lt;li&gt;Develop and implement measurement strategies, as required, to evaluate campaign effectiveness and report on ROI to clients&lt;/li&gt;
&lt;li&gt;Manage multiple projects simultaneously, balancing competing priorities and timelines&lt;/li&gt;
&lt;li&gt;Champion inclusiveness, diversity, and equity in all aspects of work&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Stay abreast of industry trends, ensuring a relevant and fresh approach&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;How we help you Thrive:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt; 25 days annual leave + 1 Volunteer Day &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Bupa Healthcare&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Enhanced Maternity, Adoption and Shared Parental Leave&amp;nbsp;&lt;/li&gt;
&lt;li&gt;We have a Flexible Working Model with core working hours: 10am – 4pm&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A 1.5:1 Matching Pension Structure&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Wellbeing and Health: Up to £25.00 per month towards physical or online exercise class membership, Unmind membership, LifeWorks tool and annual eye tests and development budgets and Wellbeing incentives and activities throughout the year &amp;nbsp;&lt;/li&gt;
&lt;li&gt;Season Ticket Loan and Cycle to Work Scheme&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Life Assurance&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p class=&quot;x_MsoNormal&quot;&gt;Our ambition is to attract the very best diverse talent to Ogilvy, and to be the employer of choice in the UK. We want everyone to feel welcome when they join us, and once they’re here, for them to want to stay with us, grow their career, and to feel they belong with us.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We are an equal opportunity employer and we’re committed to creating an inclusive, welcoming environment for everyone who wants to work at Ogilvy. For us, diversity, equity and inclusion is integrated into everything that we do. We believe that for creativity to flourish, everything about how we work must have diversity at its core. Your race, colour, ethnic, religion, gender, gender identity, national origin, sexual orientation, age, marital status, disability, have no bearing on our hiring decisions, but we encourage everyone to feel free to express their true selves in an environment we are consistently striving to make as inclusive as possible.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;We aim to facilitate an accessible and positive application experience for all candidates. If you require any adjustments from us to support you through the process or expect to require any adjustments to working conditions to be able to best perform in the role, please let us know. We are happy to consider all reasonable adjustments.&lt;/p&gt;
&lt;p class=&quot;x_MsoNoSpacing&quot;&gt;If you live with a disability and you would like to take advantage of our offer of a guaranteed interview under the Disability Confident Scheme, please ensure you fill out our voluntary Equal Opportunities Questionnaire when applying.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p&gt;&lt;strong&gt;Firmus Technologies&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;baa2b379-a6d3-56f4-af2b-6a08de9434e5|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469777841,&amp;quot;Aeonik&amp;quot;,469777842,&amp;quot;Aeonik&amp;quot;,469777843,&amp;quot;Aeonik&amp;quot;,469777844,&amp;quot;Aeonik&amp;quot;,469769226,&amp;quot;Aeonik&amp;quot;,201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,201341986,&amp;quot;1&amp;quot;,268442635,&amp;quot;20&amp;quot;,335551500,&amp;quot;197122&amp;quot;,335559740,&amp;quot;264&amp;quot;,201341983,&amp;quot;0&amp;quot;,335559738,&amp;quot;145&amp;quot;,469775450,&amp;quot;FIR Body&amp;quot;,201340122,&amp;quot;2&amp;quot;,134234082,&amp;quot;true&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;FIRBody&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Body Text&amp;quot;]}&quot;&gt;Firmus Technologies is a global&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;leader&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt; pioneering the development &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;and operation of efficient AI infrastructure across Asia Pacific.&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:145,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;Founded in Australia in 2019, our mission is to create the most efficient AI infrastructure by &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;combining&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;cutting-edge&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;&amp;nbsp;technology with a steadfast commitment to sustainability.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:145,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;At Firmus, we are unique in our approach. We design, build, and&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;operate&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt; a new class of digital &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;infrastructure – the AI Factory. Through our model-to-grid technology approach, we have pushed &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;the boundaries of multi-generational liquid cooling systems, energy management, AI software &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;orchestration, and construction. For our customers, this approach allows us to make every watt &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;count and deliver low-cost AI tokens globally.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:145,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Firmus AI Cloud&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;baa2b379-a6d3-56f4-af2b-6a08de9434e5|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469777841,&amp;quot;Aeonik&amp;quot;,469777842,&amp;quot;Aeonik&amp;quot;,469777843,&amp;quot;Aeonik&amp;quot;,469777844,&amp;quot;Aeonik&amp;quot;,469769226,&amp;quot;Aeonik&amp;quot;,201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;1&amp;quot;,201342449,&amp;quot;1&amp;quot;,201341986,&amp;quot;1&amp;quot;,268442635,&amp;quot;20&amp;quot;,335551500,&amp;quot;197122&amp;quot;,335559740,&amp;quot;264&amp;quot;,201341983,&amp;quot;0&amp;quot;,335559738,&amp;quot;145&amp;quot;,469775450,&amp;quot;FIR Body&amp;quot;,201340122,&amp;quot;2&amp;quot;,134234082,&amp;quot;true&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;FIRBody&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Body Text&amp;quot;]}&quot;&gt;Our large-scale GPU cloud platform, Firmus AI Cloud, is purpose-built &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;to deliver energy-efficient AI&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;compute&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;&amp;nbsp;at scale to customers.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:145,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;It empowers developers, enterprises, educational institutions, and government users to train and &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;deploy AI models with unmatched efficiency and cost savings. With an ever-growing suite of services &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;and applications, we are committed to delivering a cloud experience that is market-leading, &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;FIR Body&quot;&gt;proprietary, and built to scale.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:145,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;ROLE SUMMARY&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Firmus Technologies is seeking a Principal Engineer, Platform to own the platform Firmus engineers build and release on, in public cloud and in our own data centres. Self-service and security come first: through one golden path, an engineer should be able to create a service, get an environment, and ship to production securely with minimal support. Everything you design must work across sites and scale to hundreds of thousands of GPUs in gigawatt-scale AI factories.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt;KEY&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;No Spacing&quot;&gt; RESPONSIBILITIES&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Architecture and Decisions&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245418&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Own the architecture of the engineering platform and its multi-site management plane, in public cloud and on premises. Set a target architecture two to three years ahead and plan the steps from today&#39;s system to it.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Design the platform around a repeatable scaling unit. Capacity grows in identical units, a failure stays inside one unit or site, and each site meets a defined standard before it carries the platform.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Decide how internal Kubernetes and hypervisor clusters are built, networked, upgraded, and recovered. Keep Kubernetes conformant and close to upstream releases, with upgrades that need no downtime. New sites come up from code and the site deployment kit, and recovery is tested regularly.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Decide how services are packaged, released, and promoted with progressive rollout, and how a failed release is rolled back and contained across sites.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Lead design reviews for significant changes across the teams, sign off architecture decision records, and settle technical disputes escalated by engineers. Decide at pace with incomplete information, write down the assumptions, and revisit a decision when the evidence changes.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Build and Evolve&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245418&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Own engineer self-service with an API-first design. The CLI, automation, and any developer portal all use the same platform API. Treat every ticket to the platform team as a gap in self-service and close the most common ones first.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Keep a service catalogue in code, with an owner for every service and scorecards that show each team where its services stand against the golden path, production-readiness, and security standards.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;8&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Provide multi-cluster deployment for internal teams and the customer product: one pipeline to every region and data centre, the customer product isolated from internal workloads, and sites that keep running when the orchestrator is unreachable.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;21&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;9&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Let AI agents work on the delivery path under the same controls as engineers, with their own identity, least privilege, sandboxing, and a person approving every production change.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
